mapper.select:
select ecb.id, ecb.contract_code , ecb.org_id, ecb.create_time , ecb.receivable_outtax_balance , ecb.receivable_service_outtax_balance from eg_contract_balance ecb inner join eg_pay_vat epv on epv.contract_code = ecb.contract_code and epv.org_id = ecb.org_id and epv.del_flag = '0' where ecb.del_flag ='0'
and epv.id in
#{item}

select ecbl.id, ecbl.contract_code , ecbl.org_id, ecbl.create_time , ecbl.receivable_residual_value_balance, ecbl.receivable_outtax_balance , ecbl.receivable_service_outtax_balance from eg_contract_balance_latest ecbl inner join eg_pay_vat epv on epv.contract_code = ecbl.contract_code and epv.org_id = ecbl.org_id and epv.del_flag = '0' where ecbl.del_flag ='0'
and epv.id in
#{item}

select erp.id, erp.contract_code , erp.org_id, erp.create_time , erp.service_fee_received, erp.actual_repayment_date from eg_repayment_plan erp inner join eg_pay_vat epv on epv.contract_code = erp.contract_code and epv.org_id = erp.org_id and epv.del_flag = '0' where erp.del_flag ='0'
and epv.id in
#{item}

select a.execute_date, a.contract_code, a.org_id, coalesce (a.amount::numeric ,0) amount from ( select execute_date, query_field::json ->>'CONTRACT_CODE' as contract_code, query_field::json ->>'ORG_ID' as org_id, query_field::json ->>'AMOUNT' as amount from eg_check_common_data where business_type ='ysxxs'
and query_field::json ->>'CONTRACT_CODE' in
#{item}
and query_field::json ->>'ORG_ID' in
#{item}
) a
